import Foundation
import MLX
import MLXLMCommon

/// Modalities generated by an LFM3-Omni response.
public enum LFM3OmniGenerationMode: Sendable {
    case automatic
    case text
    case audio
    case interleaved
}

/// Sampling settings for text tokens and speech frames.
public struct LFM3OmniGenerationParameters: Sendable {
    public var mode: LFM3OmniGenerationMode
    public var maxSteps: Int
    public var textTemperature: Float
    public var audioTemperature: Float
    public var audioTopK: Int
    public var textRepetitionPenalty: Float
    public var audioRepetitionPenalty: Float
    public var seed: UInt64?

    public init(
        mode: LFM3OmniGenerationMode = .automatic, maxSteps: Int = 512,
        textTemperature: Float = 0.7, audioTemperature: Float = 0.4, audioTopK: Int = 0,
        textRepetitionPenalty: Float = 1.05, audioRepetitionPenalty: Float = 1.2,
        seed: UInt64? = nil
    ) {
        self.mode = mode
        self.maxSteps = maxSteps
        self.textTemperature = textTemperature
        self.audioTemperature = audioTemperature
        self.audioTopK = audioTopK
        self.textRepetitionPenalty = textRepetitionPenalty
        self.audioRepetitionPenalty = audioRepetitionPenalty
        self.seed = seed
    }

    func validate(codebookSize: Int) throws {
        guard maxSteps > 0, textTemperature.isFinite, textTemperature >= 0,
            audioTemperature.isFinite, audioTemperature >= 0,
            audioTopK >= 0, audioTopK <= codebookSize,
            textRepetitionPenalty.isFinite, textRepetitionPenalty > 0,
            audioRepetitionPenalty.isFinite, audioRepetitionPenalty > 0
        else { throw VLMError.processing("Invalid LFM3-Omni generation settings") }
    }
}

enum LFM3OmniGenerationEvent {
    case token(Int)
    case audio(MLXArray)
    case audioEnd
}

struct LFM3OmniGenerationResult {
    let tokens: [Int]
    let codes: MLXArray
    let stopReason: GenerateStopReason
}

private func penalized(_ logits: MLXArray, history: [Int], penalty: Float) -> MLXArray {
    let scores = logits.asType(.float32)
    if penalty != 1, !history.isEmpty {
        let indices = MLXArray(Array(Set(history)).sorted())
        let seen = scores[indices]
        scores[indices] = MLX.where(seen .< 0, seen * penalty, seen / penalty)
    }
    return scores
}

extension LFM3OmniDepthDecoder {
    func sampleFrame(
        hidden: MLXArray, sampler: any LogitSampler, order: MLXArray,
        history: [[Int]], penalty: Float
    ) throws -> MLXArray {
        let permutation = order.asArray(Int.self)
        guard permutation.count == config.codebooks, Set(permutation) == Set(0 ..< config.codebooks)
        else {
            throw VLMError.processing("Invalid LFM3-Omni codebook reveal order")
        }
        let codes = MLXArray.zeros([1, config.codebooks], dtype: .int32)
        let masked = MLXArray.ones([1, config.codebooks], dtype: .bool)
        var offset = 0
        for count in config.schedule {
            let logits = try self(hidden: hidden, codes: codes, masked: masked)
            for book in permutation[offset ..< offset + count] {
                let scores = penalized(
                    logits[0, book], history: history.map { $0[book] }, penalty: penalty)
                codes[0, book] = sampler.sample(logits: scores.expandedDimensions(axis: 0))
                    .squeezed()
            }
            masked[0, MLXArray(Array(permutation[offset ..< offset + count]))] = MLXArray(false)
            offset += count
        }
        return codes[0]
    }
}

extension LFM3Omni {
    func generateOmni(
        input: LMInput, audioOutputCodes: MLXArray? = nil,
        parameters: LFM3OmniGenerationParameters, stopTokens: Set<Int>,
        emit: (LFM3OmniGenerationEvent) throws -> Void
    ) throws -> LFM3OmniGenerationResult {
        try Task.checkCancellation()
        try parameters.validate(codebookSize: config.codebookSize)
        guard stopTokens.allSatisfy({ $0 >= 0 && $0 < vocabularySize }) else {
            throw VLMError.processing("Invalid LFM3-Omni stop token")
        }
        var embedded = try embeddings(input, audioOutputCodes: audioOutputCodes)
        let last = input.text.tokens.asArray(Int.self).last!
        var generatedPrefix = [Int]()
        var mode = parameters.mode
        if mode == .automatic {
            if last == config.audioStartToken || last == config.audioOutputToken {
                mode = .audio
            } else if last == config.mixedStartToken {
                mode = .interleaved
            } else {
                mode = .text
            }
            if last == config.audioOutputToken, let audioOutputCodes,
                any(audioOutputCodes[-1] .== config.audioEndCode).item(Bool.self)
            {
                mode = .text
            }
        } else {
            let marker: Int? =
                switch mode {
                case .audio:
                    (last == config.audioStartToken || last == config.audioOutputToken)
                        ? nil : config.audioStartToken
                case .interleaved: last == config.mixedStartToken ? nil : config.mixedStartToken
                default: nil
                }
            if let marker {
                generatedPrefix.append(marker)
                embedded = concatenated(
                    [embedded, languageModel.model.embed(MLXArray([marker]).reshaped(1, 1))],
                    axis: 1)
            }
        }
        let cache = try newCache(parameters: nil)
        var hidden = try prefillHidden(embedded, cache: cache, prefill: .init())[0..., -1, 0...]
        let textSampler = GenerateParameters(
            temperature: parameters.textTemperature, seed: parameters.seed
        ).sampler()
        let audioSampler = GenerateParameters(
            temperature: parameters.audioTemperature,
            topK: parameters.audioTopK, seed: parameters.seed.map { $0 &+ 1 }
        ).sampler()
        let random =
            parameters.seed.map { MLXRandom.RandomState(seed: $0 &+ 2) } ?? MLXRandom.RandomState()
        let placeholderIDs = [
            config.audioToken, config.audioOutputToken,
            config.visionLanguage.imageToken, config.visionLanguage.videoToken,
        ]
        let suppressed =
            parameters.mode == .text
            ? placeholderIDs + [config.audioStartToken, config.mixedStartToken] : placeholderIDs
        var tokens = generatedPrefix
        var frames = [MLXArray]()
        var textHistory = [Int]()
        var audioHistory = [[Int]]()
        var speaking = false
        var textDone = false
        var slots = config.textBlock
        var stopped = false
        for _ in 0 ..< parameters.maxSteps {
            try Task.checkCancellation()
            let interleaving = mode == .interleaved
            let next: MLXArray
            if mode == .audio || (interleaving && speaking) {
                var codes = try depthDecoder.sampleFrame(
                    hidden: hidden, sampler: audioSampler,
                    order: MLXRandom.permutation(config.codebooks, key: random),
                    history: audioHistory, penalty: parameters.audioRepetitionPenalty)
                if any(codes .== config.audioEndCode).item(Bool.self) {
                    codes = MLXArray.full([config.codebooks], values: MLXArray(config.audioEndCode))
                        .asType(.int32)
                    try emit(.audioEnd)
                    mode = .text
                } else {
                    audioHistory.append(codes.asArray(Int.self))
                    if audioHistory.count > 64 { audioHistory.removeFirst() }
                    try emit(.audio(codes))
                }
                // Keep terminal frames for exact replay of a spoken conversation.
                frames.append(codes)
                tokens.append(config.audioOutputToken)
                next = try codebookEmbeddings(codes.expandedDimensions(axis: 0)).expandedDimensions(
                    axis: 1)
            } else {
                let scores = penalized(
                    languageModel.logits(hidden)[0], history: textHistory,
                    penalty: parameters.textRepetitionPenalty)
                scores[MLXArray(suppressed)] = MLXArray(-Float.infinity)
                let token = textSampler.sample(logits: scores.expandedDimensions(axis: 0)).item(
                    Int.self)
                textHistory.append(token)
                if textHistory.count > 32 { textHistory.removeFirst() }
                tokens.append(token)
                try emit(.token(token))
                if token == config.textEndToken {
                    if interleaving {
                        textDone = true
                        speaking = true
                    } else {
                        stopped = true
                    }
                } else if stopTokens.contains(token) {
                    stopped = true
                } else if !interleaving {
                    if token == config.audioStartToken {
                        mode = .audio
                    } else if token == config.mixedStartToken {
                        mode = .interleaved
                        slots = config.textBlock
                        speaking = false
                        textDone = false
                    }
                }
                next = languageModel.model.embed(MLXArray([token]).reshaped(1, 1))
            }
            if stopped { break }
            if interleaving && !textDone {
                slots -= 1
                if slots == 0 {
                    speaking.toggle()
                    slots = speaking ? config.audioBlock : config.textBlock
                }
            }
            hidden = languageModel.model(embeddings: next, cache: cache)[0..., -1, 0...]
            eval(hidden, cache)
        }
        let codes =
            frames.isEmpty ? MLXArray.zeros([0, config.codebooks], dtype: .int32) : stacked(frames)
        return .init(tokens: tokens, codes: codes, stopReason: stopped ? .stop : .length)
    }
}
